  lie_steering_activation plan{};
  plan.abi_version = LIE_STEERING_ACTIVATION_ABI;
  plan.struct_bytes = sizeof(plan);
  lie_error detail{};
  const auto bytes = std::uint64_t{tokens} * branches * c.hidden_size * sizeof(float);
