        bytes, std::uint64_t{c.hidden_size} * sizeof(float), &plan, &detail) != LIE_OK) {
    AssignError(error_msg, detail.message);
    return false;
  }
  return Check(lie_hip_direction_remove(values,
      lie_directions_ + std::size_t{layer} * c.hidden_size, plan, stream_),
      "directional steering", error_msg);
