bool Executor::LieChangeSteering(Session& session, float ffn, float attention,
                                  std::string* error_msg) const {
  if (session.owner_ != this || session.spec_tokens_ ||
      !std::isfinite(ffn) || !std::isfinite(attention) ||
      ffn < -100.0f || ffn > 100.0f || attention < -100.0f || attention > 100.0f ||
      ((ffn != 0.0f || attention != 0.0f) && !lie_directions_)) {
    AssignError(error_msg, "invalid live steering scales or outstanding verification");
    return false;
  }
  if (session.lie_ffn_scale_ == ffn && session.lie_attention_scale_ == attention)
    return true;
  if (!Check(hipStreamSynchronize(stream_), "live steering drain", error_msg))
    return false;
  while (!session.graphs_.empty()) {
    const auto it = session.graphs_.begin();
    if (!Check(hipGraphExecDestroy(it->second), "live steering graph", error_msg))
      return false;
    session.graphs_.erase(it);
  }
  session.warmed_.clear();
  session.lie_ffn_scale_ = ffn == 0.0f ? 0.0f : ffn;
  session.lie_attention_scale_ = attention == 0.0f ? 0.0f : attention;
  return true;
}
